SELECT

FROM SLEEP_COMMENT_HEADER
WHERE
LOGIC_DEL = 0

    AND SOURCE = #{dto.source}


    AND USER_ID = #{dto.userId}


    AND USER_NAME = #{dto.userName}


    AND TITLE = #{dto.title}


    AND CONTENT = #{dto.content}


    AND LEVEL = #{dto.level}


    AND OPERATE_TIME = #{dto.operateTime}


    AND FLOOR = #{dto.floor}


    AND CONTENT_TYPE = #{dto.contentType}


    AND URL = #{dto.url}


    AND GRADE = #{dto.grade}


    AND COMMENT_NUM = #{dto.commentNum}

ORDER BY create_time DESC

